import * as React from 'react'
import { cn } from '@/lib/utils'
import { Button } from '@/components/ui/button'

export interface EmptyStateProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Icon element rendered inside the accent-tinted tile. Pass a Phosphor (or any) icon node. */
  icon: React.ReactNode
  /** Primary heading. */
  title: string
  /** Supporting text below the heading. */
  subtitle: string
  /**
   * Label for the optional call-to-action button. Renders an accent `Button`.
   * For anything the shorthand cannot express -- an icon in the button, a
   * different variant, a `<label>` wrapping a file input -- use `action`.
   */
  ctaLabel?: string
  /** Handler for the optional call-to-action button. */
  onCta?: () => void
  /**
   * Arbitrary call-to-action node, rendered in place of the `ctaLabel` button.
   * Takes precedence over `ctaLabel`/`onCta` when both are given.
   */
  action?: React.ReactNode
}

/**
 * Centred empty-state layout: icon tile + title + subtitle + optional CTA.
 *
 * The icon tile uses the accent colour for its background. Pass translated
 * strings -- the DS is i18n-free.
 *
 * Two ways to give it an action. `ctaLabel` + `onCta` is the shorthand and
 * renders an accent `Button`. `action` is the slot, for when the shorthand is
 * too narrow: an upload button that needs an icon, a secondary variant, or a
 * control that is not a button at all. The slot was added in 0.6.0 after an
 * external consumer hit the shorthand's ceiling building a file drop zone.
 */
export const EmptyState = React.forwardRef<HTMLDivElement, EmptyStateProps>(function EmptyState(
  { icon, title, subtitle, ctaLabel, onCta, action, className, ...props },
  ref,
) {
  return (
    <div
      ref={ref}
      className={cn('flex flex-col items-center justify-center text-center py-20 px-4', className)}
      {...props}
    >
      <div className="w-16 h-16 rounded-2xl bg-[var(--color-accent-50)] dark:bg-[var(--color-neutral-800)] flex items-center justify-center mb-4">
        {icon}
      </div>
      <h2 className="text-lg font-semibold text-[var(--color-text-primary-light)] dark:text-[var(--color-text-primary-dark)] mb-1">
        {title}
      </h2>
      <p className="text-sm text-[var(--color-text-secondary-light)] dark:text-[var(--color-text-secondary-dark)] mb-6 max-w-xs">
        {subtitle}
      </p>
      {action ??
        (ctaLabel && onCta ? (
          <Button variant="accent" onClick={onCta}>
            {ctaLabel}
          </Button>
        ) : null)}
    </div>
  )
})

EmptyState.displayName = "EmptyState"
